//! Generated docs: `docs/cli.md` and the man pages, both built from the clap definitions in main.rs.
use crate::Cli;
use crate::out::{Done, internal};
use clap::{Command, CommandFactory};
use serde_json::json;
use std::fmt::Write as _;
use std::path::Path;

/// Writes `cli.md` and `man/*.1` into `dir`. Man pages from an earlier run are removed first.
pub fn write(dir: &Path) -> Done {
    let mut root = Cli::command();
    root.build();
    std::fs::create_dir_all(dir).map_err(internal)?;

    let mut md = String::from(
        "# Orbit CLI\n\nGenerated by `just docs` from the clap definitions in `crates/orbit-cli`. Do not edit by hand.\n\n",
    );
    markdown(&root, "orbit", 2, &mut md);
    let md_path = dir.join("cli.md");
    std::fs::write(&md_path, md).map_err(internal)?;

    let man_dir = dir.join("man");
    if man_dir.exists() {
        std::fs::remove_dir_all(&man_dir).map_err(internal)?;
    }
    std::fs::create_dir_all(&man_dir).map_err(internal)?;
    clap_mangen::generate_to(Cli::command(), &man_dir).map_err(internal)?;

    let human = format!("wrote {} and {}", md_path.display(), man_dir.display());
    Ok((
        human,
        json!({ "markdown": md_path.display().to_string(), "man": man_dir.display().to_string() }),
    ))
}

/// One section per command, its long help in a text block, then its visible subcommands.
fn markdown(cmd: &Command, path: &str, depth: usize, out: &mut String) {
    let help = cmd.clone().render_long_help().to_string();
    let _ = writeln!(
        out,
        "{} `{path}`\n\n```text\n{}\n```\n",
        "#".repeat(depth),
        help.trim_end()
    );
    for sub in cmd
        .get_subcommands()
        .filter(|s| !s.is_hide_set() && s.get_name() != "help")
    {
        markdown(sub, &format!("{path} {}", sub.get_name()), depth + 1, out);
    }
}
